// Pure logic behind the inline-edit display-name field
export function createField(initial, onSave){
  let saved = initial, draft = initial, error = null;
  return {
    type(v){ draft = v.slice(0,40); },
    key(k){ if(k==='Enter') commit(); },
    blur(){ commit(); },
    state(){ return {saved, draft, error}; }
  };
  function commit(){ const v=draft.trim(); saved=v; onSave(v); }
}

