export function NameField({value,onSave}){
  const [v,setV]=useState(value);
  return <input value={v} onChange={e=>setV(e.target.value)}
    onKeyDown={e=>{ if(e.key==='Enter') onSave(v.trim()) }}
    onBlur={()=>onSave(v.trim())} maxLength={40}/>;
}

